'use strict';

const path = require('path');

/**
 * FlowStudio Lite — History origin classification (v2.34.0,
 * owner's Problem 7).
 *
 * The History page lists the output folder's files, but nothing
 * in a bare folder listing says whether a file was generated by
 * this app or is a local file the owner dropped into the same
 * folder — the two mixed invisibly. The engine's queue_tasks
 * records are the evidence: every generated download stored its
 * file_path / file_name there. Classification for one listed file:
 *
 *   1. PATH match — a record whose file_path IS this file's
 *      absolute path (normalised, case-insensitive: Windows) →
 *      "flow". This is the strong evidence.
 *   2. NAME match — no path match, but a record carries this
 *      file's NAME. Project runs move the download_folder setting
 *      to the project subfolder, and the owner may move files
 *      between folders afterwards; a generated file must never be
 *      mislabelled "local" just because its record points at a
 *      previous folder. When in doubt, the DB's file_name history
 *      wins → "flow".
 *   3. No record at all → "local". A record is NEVER fabricated
 *      for a local file; this module only reads.
 *
 * Pure: the records are injected (db rows in the bridge, literals
 * in tests).
 */

function normPath(p) {
  return String(p || '').replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase();
}

function classifyOrigin(fileName, absPath, records) {
  const targetPath = normPath(absPath);
  const targetName = String(fileName || '').toLowerCase();
  let nameHit = false;
  for (const r of Array.isArray(records) ? records : []) {
    if (!r) continue;
    if (r.file_path && targetPath && normPath(r.file_path) === targetPath) {
      return 'flow';
    }
    if (targetName && r.file_name &&
        String(r.file_name).toLowerCase() === targetName) {
      nameHit = true;
    }
  }
  return nameHit ? 'flow' : 'local';
}

/**
 * Attach `origin` to a folder listing ({name, size, mtime}[]).
 * A file entry may carry a `project` (the output folder's child
 * folder it was listed from — History's project groups); its
 * absolute path is then inside that subfolder, so the PATH
 * evidence compares against the file's real location.
 */
function withOrigins(files, dir, records) {
  return (Array.isArray(files) ? files : []).map(f => ({
    ...f,
    origin: classifyOrigin(
      f.name,
      f.project ? path.join(dir, f.project, f.name) : path.join(dir, f.name),
      records),
  }));
}

module.exports = { classifyOrigin, withOrigins };
